{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2174-06-06 05:00:00",
      "speaker": "Doctor",
      "text": "Good morning. I'm Dr. Lee, one of the surgical team. You're here today for your gastric bypass reversal surgery. How are you feeling?"
    },
    {
      "turn_number": 2,
      "time": "2174-06-06 05:02:00",
      "speaker": "Patient",
      "text": "Hi, Doctor. I’m a little nervous, but okay. I’ve been having those low blood sugar episodes a lot lately, even when I eat."
    },
    {
      "turn_number": 3,
      "time": "2174-06-06 05:04:00",
      "speaker": "Doctor",
      "text": "Yes, that’s what we’re hoping to fix with this reversal. The bypass has been causing your body to absorb food too quickly, leading to hypoglycemia. We’ll reconnect your stomach and intestines to slow things down."
    },
    {
      "turn_number": 4,
      "time": "2174-06-06 05:06:00",
      "speaker": "Patient",
      "text": "Right. I’ve had this for years, and nothing else helped. The specialists said reversal was my best option."
    },
    {
      "turn_number": 5,
      "time": "2174-06-06 05:08:00",
      "speaker": "Doctor",
      "text": "Exactly. We’ve reviewed your history, including your past ulcers and bacterial overgrowth. The plan is laparoscopic reversal, but we may convert to open if needed. Any questions before we proceed?"
    },
    {
      "turn_number": 6,
      "time": "2174-06-06 05:10:00",
      "speaker": "Patient",
      "text": "Will I still need the G-tube after this?"
    },
    {
      "turn_number": 7,
      "time": "2174-06-06 05:12:00",
      "speaker": "Doctor",
      "text": "For now, yes. It’s there to help with stomach decompression after surgery. We’ll clamp it in a few days once your bowels start moving again."
    },
    {
      "turn_number": 8,
      "time": "2174-06-06 05:14:00",
      "speaker": "Patient",
      "text": "Okay. And pain control? Last time I had surgery, it was rough."
    },
    {
      "turn_number": 9,
      "time": "2174-06-06 05:16:00",
      "speaker": "Doctor",
      "text": "We’ll start with an epidural for the first day or two, then switch to a PCA pump. Once you’re eating, we’ll move to oral pain meds like hydromorphone."
    },
    {
      "turn_number": 10,
      "time": "2174-06-06 05:18:00",
      "speaker": "Patient",
      "text": "Alright, that sounds better. Thank you."
    },
    {
      "turn_number": 11,
      "time": "2174-06-06 05:20:00",
      "speaker": "Doctor",
      "text": "You’re welcome. The anesthesia team will be in soon. We’ll see you after the surgery in recovery."
    },
    {
      "turn_number": 12,
      "time": "2174-06-06 14:00:00",
      "speaker": "Doctor",
      "text": "Hi again. You’re in the recovery unit. The surgery went well—laparoscopic bypass reversal completed without complications. You were extubated and stable."
    },
    {
      "turn_number": 13,
      "time": "2174-06-06 14:02:00",
      "speaker": "Patient",
      "text": "That’s good to hear. I feel groggy, but okay. My stomach feels… different?"
    },
    {
      "turn_number": 14,
      "time": "2174-06-06 14:04:00",
      "speaker": "Doctor",
      "text": "It will take time to adjust. We’ve reconnected your stomach to the jejunum, so digestion will be more normal. You’re NPO for now—G-tube is on gravity drainage."
    },
    {
      "turn_number": 15,
      "time": "2174-06-06 14:06:00",
      "speaker": "Patient",
      "text": "And the staples? I see bandages."
    },
    {
      "turn_number": 16,
      "time": "2174-06-06 14:08:00",
      "speaker": "Doctor",
      "text": "Yes, small incisions were stapled closed. They’ll heal in a few weeks. We’ll monitor for infection, but you’re on antibiotics and heparin to prevent clots."
    },
    {
      "turn_number": 17,
      "time": "2174-06-06 14:10:00",
      "speaker": "Patient",
      "text": "Okay. And my blood sugar? Should I check it?"
    },
    {
      "turn_number": 18,
      "time": "2174-06-06 14:12:00",
      "speaker": "Doctor",
      "text": "We’re monitoring it every four hours. Your last was 111—normal. With the reversal, we expect fewer hypoglycemic episodes long-term."
    },
    {
      "turn_number": 19,
      "time": "2174-06-07 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re doing well. We did an upper GI study this morning with contrast. No leaks or blockages—great news."
    },
    {
      "turn_number": 20,
      "time": "2174-06-07 08:02:00",
      "speaker": "Patient",
      "text": "That’s a relief. Can I start drinking water yet?"
    },
    {
      "turn_number": 21,
      "time": "2174-06-07 08:04:00",
      "speaker": "Doctor",
      "text": "Not yet. We’ll wait until tomorrow. For now, just keep using your mouth swabs. We want to make sure your stomach is healing."
    },
    {
      "turn_number": 22,
      "time": "2174-06-07 08:06:00",
      "speaker": "Patient",
      "text": "Makes sense. My pain is better—still there, but manageable."
    },
    {
      "turn_number": 23,
      "time": "2174-06-07 08:08:00",
      "speaker": "Doctor",
      "text": "Good. We’ll keep the epidural going today, then transition to oral meds soon. We’re also encouraging you to sit up and walk later."
    },
    {
      "turn_number": 24,
      "time": "2174-06-07 08:10:00",
      "speaker": "Patient",
      "text": "I’ll try. I don’t want to get a blood clot."
    },
    {
      "turn_number": 25,
      "time": "2174-06-07 08:12:00",
      "speaker": "Doctor",
      "text": "Exactly. Early movement helps prevent that. You’re also wearing compression boots."
    },
    {
      "turn_number": 26,
      "time": "2174-06-08 07:30:00",
      "speaker": "Doctor",
      "text": "Morning. Your labs look good. Hemoglobin is stable, no signs of bleeding. We’re going to clamp the G-tube today and start small sips of water."
    },
    {
      "turn_number": 27,
      "time": "2174-06-08 07:32:00",
      "speaker": "Patient",
      "text": "Finally! Can I have more than a sip?"
    },
    {
      "turn_number": 28,
      "time": "2174-06-08 07:34:00",
      "speaker": "Doctor",
      "text": "We’ll start slow—just a few sips every 15 minutes. If you tolerate it, we’ll advance to clear liquids tomorrow."
    },
    {
      "turn_number": 29,
      "time": "2174-06-08 07:36:00",
      "speaker": "Patient",
      "text": "And my blood sugar? I felt a little shaky earlier."
    },
    {
      "turn_number": 30,
      "time": "2174-06-08 07:38:00",
      "speaker": "Doctor",
      "text": "We checked it—123, which is fine. Sometimes the body reacts to stress. Keep monitoring, and let us know if you feel dizzy or sweaty."
    },
    {
      "turn_number": 31,
      "time": "2174-06-09 08:00:00",
      "speaker": "Doctor",
      "text": "You’re doing great. You tolerated water, so we’re advancing you to clear liquids—broth, apple juice, gelatin."
    },
    {
      "turn_number": 32,
      "time": "2174-06-09 08:02:00",
      "speaker": "Patient",
      "text": "Can I have juice? I’ve been craving something sweet."
    },
    {
      "turn_number": 33,
      "time": "2174-06-09 08:04:00",
      "speaker": "Doctor",
      "text": "Yes, but small amounts. And remember, no straws or gum—those can cause bloating."
    },
    {
      "turn_number": 34,
      "time": "2174-06-09 08:06:00",
      "speaker": "Patient",
      "text": "Got it. And the pain meds? I’m on hydromorphone now?"
    },
    {
      "turn_number": 35,
      "time": "2174-06-09 08:08:00",
      "speaker": "Doctor",
      "text": "Yes, oral hydromorphone as needed. We stopped the epidural yesterday. How’s the pain on a scale of 1 to 10?"
    },
    {
      "turn_number": 36,
      "time": "2174-06-09 08:10:00",
      "speaker": "Patient",
      "text": "About a 4. Much better than yesterday."
    },
    {
      "turn_number": 37,
      "time": "2174-06-09 08:12:00",
      "speaker": "Doctor",
      "text": "Good. We’ll keep it controlled. You’re also walking more—great for recovery."
    },
    {
      "turn_number": 38,
      "time": "2174-06-10 07:45:00",
      "speaker": "Doctor",
      "text": "Today we’re advancing your diet to stage III—soft, pureed foods. Things like mashed potatoes, applesauce, yogurt."
    },
    {
      "turn_number": 39,
      "time": "2174-06-10 07:47:00",
      "speaker": "Patient",
      "text": "Can I have scrambled eggs?"
    },
    {
      "turn_number": 40,
      "time": "2174-06-10 07:49:00",
      "speaker": "Doctor",
      "text": "If they’re well-cooked and soft, yes. Small portions. We don’t want to overwhelm your stomach."
    },
    {
      "turn_number": 41,
      "time": "2174-06-10 07:51:00",
      "speaker": "Patient",
      "text": "And my vitamins? I usually take them crushed."
    },
    {
      "turn_number": 42,
      "time": "2174-06-10 07:53:00",
      "speaker": "Doctor",
      "text": "Yes, continue crushing all pills. We’ll also start you on chewable multivitamins to prevent deficiencies."
    },
    {
      "turn_number": 43,
      "time": "2174-06-11 08:00:00",
      "speaker": "Doctor",
      "text": "You’re doing really well. Ate all your meals, walking independently, pain controlled. We’re planning for discharge in a couple of days."
    },
    {
      "turn_number": 44,
      "time": "2174-06-11 08:02:00",
      "speaker": "Patient",
      "text": "That’s great. What do I need to do at home?"
    },
    {
      "turn_number": 45,
      "time": "2174-06-11 08:04:00",
      "speaker": "Doctor",
      "text": "Stay on the stage III diet until your follow-up. No straws, no gum. Monitor your blood sugar closely with your CGM."
    },
    {
      "turn_number": 46,
      "time": "2174-06-11 08:06:00",
      "speaker": "Patient",
      "text": "And if my sugar drops?"
    },
    {
      "turn_number": 47,
      "time": "2174-06-11 08:08:00",
      "speaker": "Doctor",
      "text": "Use the glucose gel we’re prescribing. One packet, wait 15 minutes. If still low, repeat. If you pass out, call 911."
    },
    {
      "turn_number": 48,
      "time": "2174-06-11 08:10:00",
      "speaker": "Patient",
      "text": "Got it. What about pain meds?"
    },
    {
      "turn_number": 49,
      "time": "2174-06-11 08:12:00",
      "speaker": "Doctor",
      "text": "You’ll have hydromorphone for breakthrough pain and acetaminophen for mild discomfort. Don’t drive while on them."
    },
    {
      "turn_number": 50,
      "time": "2174-06-12 07:50:00",
      "speaker": "Doctor",
      "text": "Last night’s labs are normal. No infection, no anemia. You’re afebrile and stable. Looks like we’re on track for discharge tomorrow."
    },
    {
      "turn_number": 51,
      "time": "2174-06-12 07:52:00",
      "speaker": "Patient",
      "text": "I’m ready to go home. But what about the staples?"
    },
    {
      "turn_number": 52,
      "time": "2174-06-12 07:54:00",
      "speaker": "Doctor",
      "text": "They’ll be removed at your follow-up. Keep the area dry—showering is okay, no baths or swimming."
    },
    {
      "turn_number": 53,
      "time": "2174-06-12 07:56:00",
      "speaker": "Patient",
      "text": "And if I see drainage?"
    },
    {
      "turn_number": 54,
      "time": "2174-06-12 07:58:00",
      "speaker": "Doctor",
      "text": "Clear drainage is normal. Cover with gauze. But if it’s yellow, green, or foul-smelling, call us."
    },
    {
      "turn_number": 55,
      "time": "2174-06-13 08:00:00",
      "speaker": "Doctor",
      "text": "Final day! You’ve passed all milestones. Tolerating diet, ambulating, no complications. Discharge is set for tomorrow morning."
    },
    {
      "turn_number": 56,
      "time": "2174-06-13 08:02:00",
      "speaker": "Patient",
      "text": "I’m so relieved. What about my other meds—like fluoxetine and aripiprazole?"
    },
    {
      "turn_number": 57,
      "time": "2174-06-13 08:04:00",
      "speaker": "Doctor",
      "text": "Resume all your home medications, but crush them. We’re also adding pantoprazole twice daily for a month to prevent reflux."
    },
    {
      "turn_number": 58,
      "time": "2174-06-13 08:06:00",
      "speaker": "Patient",
      "text": "And no NSAIDs, right?"
    },
    {
      "turn_number": 59,
      "time": "2174-06-13 08:08:00",
      "speaker": "Doctor",
      "text": "Correct. No ibuprofen or naproxen. They can cause ulcers. Use acetaminophen instead."
    },
    {
      "turn_number": 60,
      "time": "2174-06-14 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. We’re finalizing your discharge. You’re doing excellent—eating well, pain controlled, no fever."
    },
    {
      "turn_number": 61,
      "time": "2174-06-14 09:02:00",
      "speaker": "Patient",
      "text": "I feel ready. Just want to make sure I understand everything."
    },
    {
      "turn_number": 62,
      "time": "2174-06-14 09:04:00",
      "speaker": "Doctor",
      "text": "Of course. No heavy lifting over 10 pounds for six weeks. Light exercise is fine, but no abdominal crunches."
    },
    {
      "turn_number": 63,
      "time": "2174-06-14 09:06:00",
      "speaker": "Patient",
      "text": "And follow-up?"
    },
    {
      "turn_number": 64,
      "time": "2174-06-14 09:08:00",
      "speaker": "Doctor",
      "text": "In two weeks. We’ll remove staples, check healing, and review your progress. Call sooner if you have fever, severe pain, or vomiting."
    },
    {
      "turn_number": 65,
      "time": "2174-06-14 09:10:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I really appreciate all the care."
    },
    {
      "turn_number": 66,
      "time": "2174-06-14 09:12:00",
      "speaker": "Doctor",
      "text": "You’re welcome. You did great. We’ll see you in clinic soon."
    },
    {
      "turn_number": 67,
      "time": "2174-06-15 08:00:00",
      "speaker": "Doctor",
      "text": "Final check before discharge. Vital signs are stable, you’ve eaten breakfast, and your incisions look clean. All set to go home."
    },
    {
      "turn_number": 68,
      "time": "2174-06-15 08:02:00",
      "speaker": "Patient",
      "text": "I’m so glad. I feel like this surgery was the right choice."
    },
    {
      "turn_number": 69,
      "time": "2174-06-15 08:04:00",
      "speaker": "Doctor",
      "text": "We’re hopeful it will resolve your hypoglycemia. Keep monitoring, take your meds, and follow the diet."
    },
    {
      "turn_number": 70,
      "time": "2174-06-15 08:06:00",
      "speaker": "Patient",
      "text": "I will. Thank you again."
    },
    {
      "turn_number": 71,
      "time": "2174-06-15 08:08:00",
      "speaker": "Doctor",
      "text": "Take care. Call us with any concerns."
    }
  ],
  "summary": {
    "admission_start": "2174-06-06 04:46:00",
    "admission_end": "2174-06-15 14:49:00",
    "summary_paragraph": "The patient was admitted for gastric bypass reversal due to persistent post-bariatric hypoglycemia and bacterial overgrowth. She underwent a successful laparoscopic bypass reversal with no intraoperative complications. Postoperatively, she was managed with epidural and PCA pain control, transitioned to oral hydromorphone as tolerated. The G-tube was used for decompression and clamped on postoperative day 3, with diet advanced to stage III. An upper GI study on postoperative day 1 showed no leak or obstruction. She remained afebrile, hemodynamically stable, and without signs of infection or bleeding. By discharge, she was ambulating independently, tolerating a soft diet, and had pain well controlled. She was discharged home with instructions on diet, wound care, activity restrictions, and close glucose monitoring, including use of glucose gel for hypoglycemia. Follow-up was scheduled for staple removal and surgical evaluation.",
    "problems": [
      "Other hypoglycemia",
      "Postsurgical malabsorption, not elsewhere classified",
      "Surgical operation with anastomosis, bypass or graft as the cause of abnormal reaction of the patient, or of later complication, without mention of misadventure at the time of the procedure",
      "Fatty (change of) liver, not elsewhere classified",
      "Morbid (severe) obesity due to excess calories",
      "Anxiety disorder, unspecified",
      "Body mass index [BMI] 36.0-36.9, adult",
      "Polycystic ovarian syndrome",
      "Pure hypercholesterolemia",
      "Carrier or suspected carrier of Methicillin resistant Staphylococcus aureus",
      "Incisional hernia without obstruction or gangrene",
      "Postprocedural hypotension",
      "Lipodystrophy, not elsewhere classified",
      "Other adrenocortical insufficiency",
      "Post-traumatic stress disorder, unspecified"
    ]
  }
}
